import path from 'node:path';
import detectPort from 'detect-port';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { buildLegacyComponents, buildUnifiedComponents, findProjectRoot, isLegacyPlatformVersion, loadProjectConfig, } from '../../bin/configDiscovery.js';
import { runDevCommand } from '../../bin/devCommand.js';
import { createDevSessionManager } from '../../bin/sessionManager.js';
import { DevModeInterfaceNonSingleton } from '../../DevModeInterface.js';
import { DevModeUnifiedInterfaceNonSingleton } from '../../DevModeUnifiedInterface.js';
// vi.hoisted ensures these objects exist before vi.mock factories run,
// since factories are hoisted to the top of the file before module-level consts.
const { mockLegacyDevMode, mockUnifiedDevMode, mockSessionManager } = vi.hoisted(() => ({
    mockLegacyDevMode: {
        setup: vi.fn(),
        start: vi.fn(),
        cleanup: vi.fn(),
    },
    mockUnifiedDevMode: {
        setup: vi.fn(),
        start: vi.fn(),
        cleanup: vi.fn(),
    },
    mockSessionManager: {
        register: vi.fn(),
        cleanup: vi.fn(),
    },
}));
vi.mock('detect-port', () => ({ default: vi.fn() }));
// Constructors must be regular functions, not arrow functions — arrow functions
// cannot be used as constructors (they have no [[Construct]] internal slot).
vi.mock('../../DevModeInterface.ts', () => ({
    // eslint-disable-next-line prefer-arrow-callback
    DevModeInterfaceNonSingleton: vi.fn(function () {
        return mockLegacyDevMode;
    }),
}));
vi.mock('../../DevModeUnifiedInterface.ts', () => ({
    // eslint-disable-next-line prefer-arrow-callback
    DevModeUnifiedInterfaceNonSingleton: vi.fn(function () {
        return mockUnifiedDevMode;
    }),
}));
vi.mock('../../bin/configDiscovery.ts', () => ({
    findProjectRoot: vi.fn(),
    loadProjectConfig: vi.fn(),
    isLegacyPlatformVersion: vi.fn(),
    buildLegacyComponents: vi.fn(),
    buildUnifiedComponents: vi.fn(),
}));
vi.mock('../../bin/sessionManager.ts', () => ({
    createDevSessionManager: vi.fn(),
}));
const DEFAULT_PORT = 5173;
const ACCOUNT_ID = 12345;
const PROJECT_DIR = '/mock/project';
const MOCK_PROJECT_CONFIG = {
    name: 'test',
    srcDir: 'src',
    platformVersion: '2026.03',
};
describe('runDevCommand', () => {
    beforeEach(() => {
        vi.resetAllMocks();
        // detect-port: cast needed because the library's TS signature is callback-based
        vi.mocked(detectPort).mockImplementation((port) => Promise.resolve(port));
        vi.mocked(findProjectRoot).mockReturnValue(PROJECT_DIR);
        vi.mocked(loadProjectConfig).mockReturnValue(MOCK_PROJECT_CONFIG);
        vi.mocked(isLegacyPlatformVersion).mockReturnValue(false);
        vi.mocked(buildUnifiedComponents).mockResolvedValue({
            components: {},
            profileData: {},
        });
        vi.mocked(buildLegacyComponents).mockReturnValue({});
        vi.mocked(createDevSessionManager).mockResolvedValue(mockSessionManager);
        // Re-establish constructor mocks as regular functions after vi.resetAllMocks() clears them
        vi.mocked(DevModeInterfaceNonSingleton).mockImplementation(function () {
            return mockLegacyDevMode;
        });
        vi.mocked(DevModeUnifiedInterfaceNonSingleton).mockImplementation(function () {
            return mockUnifiedDevMode;
        });
        mockLegacyDevMode.setup.mockResolvedValue(undefined);
        mockLegacyDevMode.start.mockResolvedValue(undefined);
        mockLegacyDevMode.cleanup.mockResolvedValue(undefined);
        mockUnifiedDevMode.setup.mockResolvedValue(undefined);
        mockUnifiedDevMode.start.mockResolvedValue(undefined);
        mockUnifiedDevMode.cleanup.mockResolvedValue(undefined);
        mockSessionManager.register.mockResolvedValue(undefined);
        mockSessionManager.cleanup.mockResolvedValue(undefined);
    });
    afterEach(() => {
        vi.restoreAllMocks();
        process.removeAllListeners('SIGINT');
        process.removeAllListeners('SIGTERM');
    });
    describe('legacy project', () => {
        beforeEach(() => {
            vi.mocked(isLegacyPlatformVersion).mockReturnValue(true);
        });
        it('uses DevModeInterfaceNonSingleton', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(DevModeInterfaceNonSingleton).toHaveBeenCalledOnce();
            expect(DevModeUnifiedInterfaceNonSingleton).not.toHaveBeenCalled();
        });
        it('calls buildLegacyComponents with the project dir and config', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(buildLegacyComponents).toHaveBeenCalledWith(PROJECT_DIR, MOCK_PROJECT_CONFIG);
        });
        it('calls setup before start', async () => {
            const callOrder = [];
            mockLegacyDevMode.setup.mockImplementation(async () => {
                callOrder.push('setup');
            });
            mockLegacyDevMode.start.mockImplementation(async () => {
                callOrder.push('start');
            });
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(callOrder).toEqual(['setup', 'start']);
        });
    });
    describe('unified project', () => {
        it('uses DevModeUnifiedInterfaceNonSingleton', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(DevModeUnifiedInterfaceNonSingleton).toHaveBeenCalledOnce();
            expect(DevModeInterfaceNonSingleton).not.toHaveBeenCalled();
        });
        it('calls buildUnifiedComponents with the account ID', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(buildUnifiedComponents).toHaveBeenCalledWith(PROJECT_DIR, MOCK_PROJECT_CONFIG, ACCOUNT_ID);
        });
    });
    describe('project path resolution', () => {
        it('resolves a relative projectPath against cwd', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
                projectPath: 'relative/path',
            });
            expect(findProjectRoot).toHaveBeenCalledWith(path.resolve(process.cwd(), 'relative/path'));
        });
        it('uses an absolute projectPath as-is', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
                projectPath: '/absolute/path',
            });
            expect(findProjectRoot).toHaveBeenCalledWith('/absolute/path');
        });
        it('defaults to cwd when projectPath is omitted', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(findProjectRoot).toHaveBeenCalledWith(process.cwd());
        });
    });
    describe('port threading', () => {
        it('assigns consecutive ports to multiple extension instances', async () => {
            mockUnifiedDevMode.start.mockImplementation(async (args) => {
                await args.requestPorts?.([
                    { instanceId: 'ext-1' },
                    { instanceId: 'ext-2' },
                ]);
            });
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(mockSessionManager.register).toHaveBeenCalledWith([
                { serverId: 'ext-1', port: DEFAULT_PORT },
                { serverId: 'ext-2', port: DEFAULT_PORT + 1 },
            ]);
        });
        it('starts the next port from the allocated port when there is a collision', async () => {
            const ALTERNATE_PORT = 5200;
            vi.mocked(detectPort).mockImplementation((port) => Promise.resolve(port === DEFAULT_PORT ? ALTERNATE_PORT : port));
            mockUnifiedDevMode.start.mockImplementation(async (args) => {
                await args.requestPorts?.([
                    { instanceId: 'ext-1' },
                    { instanceId: 'ext-2' },
                ]);
            });
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(mockSessionManager.register).toHaveBeenCalledWith([
                { serverId: 'ext-1', port: ALTERNATE_PORT },
                { serverId: 'ext-2', port: ALTERNATE_PORT + 1 },
            ]);
        });
    });
    describe('session registration', () => {
        it('calls register with the captured ports after start', async () => {
            mockUnifiedDevMode.start.mockImplementation(async (args) => {
                await args.requestPorts?.([{ instanceId: 'ext-1' }]);
            });
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(mockSessionManager.register).toHaveBeenCalledWith([
                { serverId: 'ext-1', port: DEFAULT_PORT },
            ]);
        });
        it('skips register when createDevSessionManager returns null', async () => {
            vi.mocked(createDevSessionManager).mockResolvedValue(null);
            mockUnifiedDevMode.start.mockImplementation(async (args) => {
                await args.requestPorts?.([{ instanceId: 'ext-1' }]);
            });
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(mockSessionManager.register).not.toHaveBeenCalled();
        });
        it('skips register when start does not call requestPorts', async () => {
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(mockSessionManager.register).not.toHaveBeenCalled();
        });
        it('logs a warning and does not crash when register throws', async () => {
            mockUnifiedDevMode.start.mockImplementation(async (args) => {
                await args.requestPorts?.([{ instanceId: 'ext-1' }]);
            });
            mockSessionManager.register.mockRejectedValue(new Error('API error'));
            vi.spyOn(console, 'error').mockImplementation(() => { });
            await expect(runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            })).resolves.not.toThrow();
            expect(console.error).toHaveBeenCalledWith(expect.stringContaining('Failed to register local dev session'));
        });
    });
    describe('signal handlers', () => {
        it('calls sessionManager.cleanup and devMode.cleanup on SIGINT', async () => {
            vi.spyOn(process, 'exit').mockImplementation((() => { }));
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            const [sigintHandler] = process.rawListeners('SIGINT');
            expect(sigintHandler).toBeDefined();
            await sigintHandler();
            expect(mockSessionManager.cleanup).toHaveBeenCalledOnce();
            expect(mockUnifiedDevMode.cleanup).toHaveBeenCalledOnce();
            expect(process.exit).toHaveBeenCalledWith(0);
        });
        it('calls cleanup on SIGTERM', async () => {
            vi.spyOn(process, 'exit').mockImplementation((() => { }));
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            const [sigtermHandler] = process.rawListeners('SIGTERM');
            await sigtermHandler();
            expect(mockSessionManager.cleanup).toHaveBeenCalledOnce();
            expect(mockUnifiedDevMode.cleanup).toHaveBeenCalledOnce();
            expect(process.exit).toHaveBeenCalledWith(0);
        });
    });
    describe('error handling', () => {
        it('logs an error and calls process.exit(1) when startup throws', async () => {
            vi.mocked(findProjectRoot).mockImplementation(() => {
                throw new Error('No hsproject.json found');
            });
            const processExitSpy = vi
                .spyOn(process, 'exit')
                .mockImplementation((() => { }));
            vi.spyOn(console, 'error').mockImplementation(() => { });
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: String(ACCOUNT_ID),
            });
            expect(processExitSpy).toHaveBeenCalledWith(1);
            expect(console.error).toHaveBeenCalledWith('Error starting dev server:', 'No hsproject.json found');
        });
        it('logs an error and calls process.exit(1) when accountId is missing', async () => {
            const processExitSpy = vi
                .spyOn(process, 'exit')
                .mockImplementation((() => { }));
            vi.spyOn(console, 'error').mockImplementation(() => { });
            await runDevCommand({ port: String(DEFAULT_PORT) });
            expect(processExitSpy).toHaveBeenCalledWith(1);
            expect(console.error).toHaveBeenCalledWith('Error starting dev server:', expect.stringContaining('--account-id'));
        });
        it('logs an error and calls process.exit(1) when accountId is not a valid number', async () => {
            const processExitSpy = vi
                .spyOn(process, 'exit')
                .mockImplementation((() => { }));
            vi.spyOn(console, 'error').mockImplementation(() => { });
            await runDevCommand({
                port: String(DEFAULT_PORT),
                accountId: 'not-a-number',
            });
            expect(processExitSpy).toHaveBeenCalledWith(1);
            expect(console.error).toHaveBeenCalledWith('Error starting dev server:', expect.stringContaining('--account-id'));
        });
    });
});
